package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.base.GeneratorBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.MinimalPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.XmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.ser.PrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.DefaultXmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.StaxUtil;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import javax.xml.namespace.QName;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamWriter;
import org.codehaus.stax2.XMLStreamWriter2;
import org.codehaus.stax2.ri.Stax2WriterAdapter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.*;

public class ToXmlGenerator_writeNumber_TriageGen2Test {

    private IOContext ioContext;
    private XMLStreamWriter xmlStreamWriter;
    private ToXmlGenerator generator;
    private QName testQName;

    @Before
    public void setUp() {
        ioContext = mock(IOContext.class);
        xmlStreamWriter = mock(XMLStreamWriter.class);
        generator = spy(new ToXmlGenerator(ioContext, 0, 0, null, xmlStreamWriter));
        testQName = new QName("http://test.com", "testElement");
    }

    /**
     * Test Case 1: Verifies that if _nextName is null, handleMissingName is called.
     * We simulate this by not calling setNextName.
     */
    @Test(expected = RuntimeException.class)
    public void testWriteNumber_MissingName() throws Exception {
        // Note: handleMissingName likely throws an exception in a real scenario 
        // because you can't write a value without a name.
        doThrow(new RuntimeException("Missing Name")).when(generator).handleMissingName();

        generator.writeNumber(123L);
    }

    /**
     * Test Case 2: Verifies behavior when _nextIsAttribute is true.
     */
    @Test
    public void testWriteNumber_AsAttribute() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(true);
        long value = 456L;

        generator.writeNumber(value);

        verify(xmlStreamWriter).writeLongAttribute(
                isNull(), 
                eq(testQName.getNamespaceURI()), 
                eq(testQName.getLocalPart()), 
                eq(value)
        );
    }

    /**
     * Test Case 3: Verifies behavior when checkNextIsUnwrapped() is true.
     */
    @Test
    public void testWriteNumber_Unwrapped() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        // Mocking checkNextIsUnwrapped to return true via spy
        doReturn(true).when(generator).checkNextIsUnwrapped();

        long value = 789L;
        generator.writeNumber(value);

        verify(xmlStreamWriter).writeLong(value);
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    /**
     * Test Case 4: Verifies behavior when _xmlPrettyPrinter is NOT null (Leaf Element path).
     */
    @Test
    public void testWriteNumber_WithPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();

        PrettyPrinter mockPrinter = mock(PrettyPrinter.class);
        generator.setPrettyPrinter(mockPrinter);

        long value = 10L;
        generator.writeNumber(value);

        verify(mockPrinter).writeLeafElement(
                eq(xmlStreamWriter), 
                eq(testQName.getNamespaceURI()), 
                eq(testQName.getLocalPart()), 
                eq(value)
        );
    }

    /**
     * Test Case 5: Verifies behavior when _xmlPrettyPrinter IS null (Standard Element path).
     */
    @Test
    public void testWriteNumber_NoPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();
        // Ensure printer is null
        generator.setPrettyPrinter(null);

        long value = 20L;
        generator.writeNumber(value);

        verify(xmlStreamWriter).writeStartElement(testQName.getNamespaceURI(), testQName.getLocalPart());
        verify(xmlStreamWriter).writeLong(value);
        verify(xmlStreamWriter).writeEndElement();
    }

    /**
     * Test Case 6: Verifies that XMLStreamException is caught and rethrown 
     * via StaxUtil (simulated via the catch block logic).
     */
    @Test(expected = Exception.class)
    public void testWriteNumber_ThrowsXMLStreamException() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();

        // Force an exception in the stream writer
        doThrow(new XMLStreamException("Stream Error")).when(xmlStreamWriter).writeStartElement(any(), any());

        generator.writeNumber(1L);
    }
}
